import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const a="/eep/ini-edit-translate-2026/editor-v2-1-37-de.png",d="/eep/ini-edit-translate-2026/info-trans-v2-1-37-de.png",s="/eep/ini-edit-translate-2026/dictionary-v2-1-37-de.png",f=JSON.parse('{"title":"INI Edit Translate 2026","description":"Funktionsbeschreibung des Windows-Editors für EEP-Modell-INI-Dateien und Installation.eep mit ChatGPT-Übersetzung.","frontmatter":{"title":"INI Edit Translate 2026","description":"Funktionsbeschreibung des Windows-Editors für EEP-Modell-INI-Dateien und Installation.eep mit ChatGPT-Übersetzung."},"headers":[],"relativePath":"eep/ini-edit-translate-2026/index.md","filePath":"eep/ini-edit-translate-2026/index.md","lastUpdated":1792783045000}'),l={name:"eep/ini-edit-translate-2026/index.md"};function o(u,e,h,g,c,b){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ini-edit-translate-2026" tabindex="-1">INI Edit Translate 2026 <a class="header-anchor" href="#ini-edit-translate-2026" aria-label="Permalink to &quot;INI Edit Translate 2026&quot;">​</a></h1><p><strong>Version 2.1.38.0 · Windows 11 · .NET Framework 4.8</strong></p><p>INI Edit Translate 2026 bearbeitet Modellbeschreibungen und Installationsdateien für EEP. Die Anwendung wird von Uwe Grimm / UGSo Software entwickelt und unter der MIT-Lizenz veröffentlicht.</p><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026" target="_blank" rel="noreferrer">Quellcode und README auf GitHub</a></p><p><img src="'+a+'" alt="Aktuelles Design von Version 2.1.37 mit Lime-Menüleiste, ohne private Inhalte"></p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026/releases/download/v2.1.38/INI-Edit-Translate-2026-v2.1.38-windows.zip" target="_blank" rel="noreferrer">Windows-ZIP v2.1.38 herunterladen</a> · <a href="https://github.com/rockbaer2007/ini-edit-translate-2026/releases/tag/v2.1.38" target="_blank" rel="noreferrer">GitHub-Release und SHA-256</a></p><p>ZIP vollständig entpacken und <code>INI Edit Translate 2026.exe</code> starten. Windows 11 und .NET Framework 4.8 werden benötigt. DLLs und Sprachordner zusammen lassen. Visual Studio ist nur zum Bauen der Quellen nötig. Kein Installer erforderlich.</p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bereich</th><th>Möglichkeiten</th></tr></thead><tbody><tr><td>Modelltexte</td><td>Namen und Beschreibungen in EN/DE/FR/PL bearbeiten</td></tr><tr><td>Modellmetadaten</td><td>PDF-Verweise, Generation, Einsatzzeitraum, Land und Symbol bearbeiten</td></tr><tr><td>Bewegungsachsen und Signalfunktionen</td><td>Sprachabhängige Einträge anzeigen, bearbeiten und übersetzen</td></tr><tr><td>Installation.eep</td><td>Namen und Beschreibungen der unterstützten Installationsabschnitte bearbeiten</td></tr><tr><td>Vorschau</td><td>Originaldatei und erzeugte Dateivorschau vergleichen</td></tr><tr><td>Tabellenexport</td><td>Vollständige Tabellen als tabulatorgetrennte UTF-8-Dateien mit BOM exportieren</td></tr><tr><td>Sicherungen</td><td>Vor dem Überschreiben vorhandener INI-Dateien eine Kopie mit Originaldateinamen anlegen</td></tr></tbody></table><h2 id="chatgpt-ubersetzung" tabindex="-1">ChatGPT-Übersetzung <a class="header-anchor" href="#chatgpt-ubersetzung" aria-label="Permalink to &quot;ChatGPT-Übersetzung&quot;">​</a></h2><p>Die Anwendung verwendet ausschließlich die OpenAI Responses API. Pro Originaltext werden die drei anderen Zielsprachen gemeinsam angefordert. Es gibt keine Zwischenübersetzung über Englisch. Wiederholte Texte innerhalb derselben Aktion verwenden einen flüchtigen Cache.</p><p>Ein Fortschrittsdialog bietet <strong>Abbrechen</strong>. Das Anfragezeitlimit beträgt 60 Sekunden; maximal 24.000 Zeichen werden je Text akzeptiert. Unvollständige Antworten, fehlende Zielsprachen und veränderte Platzhalter wie <code>{0}</code>, <code>%s</code> oder <code>[e]</code> werden abgelehnt. Bei einem Fehler bleiben die vor der Übersetzung vorhandenen Texte und Tabellen erhalten.</p><p>Die Oberfläche wurde in DE/EN/FR auf beschädigte Zeichen, falsche Sprachzuordnungen und Sprachmischungen geprüft. Technische INI-Schlüssel wie <code>Name_GER</code> bleiben erhalten.</p><h2 id="einrichtung-und-bedienung" tabindex="-1">Einrichtung und Bedienung <a class="header-anchor" href="#einrichtung-und-bedienung" aria-label="Permalink to &quot;Einrichtung und Bedienung&quot;">​</a></h2><ol><li>Die Windows-ZIP über den Downloadlink herunterladen und vollständig entpacken.</li><li><code>INI Edit Translate 2026.exe</code> aus dem entpackten Ordner starten. DLLs und Sprachordner müssen bei der Anwendung bleiben.</li><li>Unter <strong>Über → Einstellungen → OpenAI-Übersetzung</strong> den eigenen API-Schlüssel und das Modell eintragen. Voreinstellung ist <code>gpt-4.1-mini</code>.</li><li>Eine gesicherte eigene Datei zunächst im Modus <strong>Nur einlesen</strong> öffnen.</li><li>Für die Übersetzung <strong>Einlesen und übersetzen</strong> oder eine Übersetzungsschaltfläche verwenden. Bei Bewegungsachsen und Signalfunktionen die Ausgangssprache auswählen.</li><li>Vorschau und Modelltexte prüfen und anschließend ausdrücklich speichern.</li></ol><p>Der Info-Dialog wählt die geprüfte Hilfe <code>Info.de.rtf</code>, <code>Info.en.rtf</code> oder <code>Info.fr.rtf</code> passend zur Oberflächensprache. Die historische <code>Info.rtf</code> bleibt unverändert als Original erhalten. Die aktuellen Hilfetexte beschreiben OpenAI und die wiederhergestellte Nachschlagehilfe.</p><h2 id="github-updates" tabindex="-1">GitHub-Updates <a class="header-anchor" href="#github-updates" aria-label="Permalink to &quot;GitHub-Updates&quot;">​</a></h2><p>Unter <strong>Über → Nach Updates suchen</strong> wird das neueste öffentliche GitHub-Release abgefragt. Es gibt keine automatische Prüfung beim Programmstart. Nur eine neuere stabile Version wird angeboten; Versionsnummer und Release-Notizen werden angezeigt.</p><p><strong>Herunterladen und installieren</strong> lädt die Windows-ZIP samt SHA-256-Prüfsumme. Download und Paketprüfung sind abbrechbar und erfolgen vor dem Schließen der Anwendung. Vor der Installation müssen offene Dateien gespeichert und Info_trans geschlossen sein. Die Installation startet erst nach Bestätigung. Ein separates Hilfsprogramm wartet auf das Ende des Editors, sichert die bisherigen Dateien und installiert das Paket.</p><p>Einstellungen und der verschlüsselte OpenAI-Schlüssel bleiben erhalten. Vorhandene IET2.FDB-, CSV-, DAT- und Konfigurationsdateien der Nachschlagehilfe sowie die ursprüngliche Info.rtf werden gesichert und nicht ersetzt. Eigene Modelldateien bleiben unangetastet. Bei einem Installationsfehler wird die Wiederherstellung der bereits ersetzten Dateien versucht; ein Bericht nennt das Ergebnis. Sicherungen und Berichte liegen unter <code>%LOCALAPPDATA%/UGSo/IET2026/updates/&lt;Kennung&gt;/</code>.</p><p>Der Updater benötigt keine Serverzugangsdaten. Prüfsummen dienen der Integritätsprüfung; es ist keine zusätzliche digitale Paketsignatur implementiert. 36 isolierte Updateprüfungen decken Download, Abbruch, Paketpfade, Datenerhalt, gesperrte Dateien und Rücknahme nach einem teilweisen Schreibfehler ab.</p><h3 id="updater-korrektur-2-1-38" tabindex="-1">Updater-Korrektur 2.1.38 <a class="header-anchor" href="#updater-korrektur-2-1-38" aria-label="Permalink to &quot;Updater-Korrektur 2.1.38&quot;">​</a></h3><p>Die Prozessübergabe verwendet jetzt einen stabilen Windows-Prozesshandle statt Modulzugriffen auf den bereits schließenden Editor. Vier zusätzliche Prüfungen decken x86/x64, bereits beendete Prozesse, falsche Identität und Zeitüberschreitungen ab. Falls der alte 2.1.37-Helfer vor der Installation scheitert, das vollständige 2.1.38-ZIP zuerst in einen neuen Ordner entpacken. Eigene Daten vorher sichern und vorhandene Datenbanken sowie Wörterbücher nicht durch Paketdateien ersetzen.</p><p>Der vollständige Ablauf von der veröffentlichten 2.1.37 zur 2.1.38 wurde an einer gesicherten Testkopie erfolgreich geprüft: GitHub-Download, Installation und automatischer Neustart. Alle 32 bisherigen Einstellungswerte, 17 geprüfte Daten-/Modelldateien und 18 vorhandene Benutzerkonfigurationen blieben erhalten. Ein synthetischer DPAPI-Testschlüssel blieb unverändert und entschlüsselbar; anschließend wurde der ursprüngliche Zustand ohne Schlüssel wiederhergestellt. Es erfolgte kein OpenAI-Aufruf. Der Neustart wurde über Prozess-ID, Dateiversionen, Hashes und Konfiguration bestätigt; die Windows-Fenstersteuerung meldete danach einen Erfassungsfehler. Der erneute lesende GitHub-Dialogtest erkannte 2.1.38 korrekt.</p><h2 id="zweites-programm-info-trans" tabindex="-1">Zweites Programm: Info_trans <a class="header-anchor" href="#zweites-programm-info-trans" aria-label="Permalink to &quot;Zweites Programm: Info_trans&quot;">​</a></h2><p>Das Paket enthält auch <code>help/Info_trans.exe</code>. <strong>Nachschlagehilfe</strong> im Haupteditor öffnet dieses separate Programm in der gewählten Sprache. Die echte <code>IET2.FDB</code> und die zugehörige native Firebird-2.5.8-Laufzeit wurden aus dem Archiv von 2019 übernommen. Eine separate Firebird-Serverinstallation ist nicht nötig.</p><p>Die Datenbank enthält 5 Immobilien- und 2 Gütereinträge sowie 2 Updateeinträge. Die Tabellen für Signale, Rollmaterial, Gleisobjekte und Landschaft sind im Original leer. Zusätzlich sind 236 Iconeinträge, 369 technische Begriffe und 2.428 bereinigte Einträge im <strong>Wörterbuch DE/EN/FR</strong> enthalten. Englisch ist die Referenz; bestätigte deutsche Korrekturen und französische Übersetzungen sind eingearbeitet. Abgetrennte Zeilen wurden zusammengeführt und vermischte Begriffe getrennt. Amerikanische und britische Fachbegriffe bleiben mit ihren Kennzeichnungen erhalten. Alle Rückfragen zur Wörterbuchprüfung sind geklärt. Die ursprüngliche DE/EN-Datei und die Quelldatenbank bleiben unverändert im vollständigen Paket erhalten.</p><p><img src="'+d+'" alt="Info_trans 2.1.37 mit Lime-Registerkarten und geladener Originaldatenbank"></p><p><img src="'+s+'" alt="Dreisprachiges Wörterbuch in Info_trans mit gut lesbaren DE-, EN- und FR-Spalten"></p><p><code>Info_trans</code> wird passend zu den nativen DLLs für x86 gebaut. Die verwaltete DLL FirebirdSql.Data.FirebirdClient 7.5.0.0 wurde mit der echten Firebird-2.5.8-Datenbank geprüft. Tests lesen nur getrennte Datenbankkopien und vergleichen alle sieben Tabellen mit der Anzeige in DE/EN/FR. Das Paket enthält die unveränderte Quelldatenbank.</p><p>Fehlende oder nicht ladbare Bestandteile werden angezeigt. SQL-Import bleibt dann gesperrt; vor einem verfügbaren manuellen SQL-Import wird die Datenbank lokal gesichert. Die automatische Programmaktualisierung bleibt deaktiviert.</p><h2 id="daten-und-datenschutz" tabindex="-1">Daten und Datenschutz <a class="header-anchor" href="#daten-und-datenschutz" aria-label="Permalink to &quot;Daten und Datenschutz&quot;">​</a></h2><p>Die neue Fassung importiert keine alten Registrierungen oder privaten Datenbanken. Einstellungen werden getrennt pro Windows-Benutzer gespeichert. OpenAI-Konfiguration und Dateisicherungen liegen unter <code>%LOCALAPPDATA%/UGSo/IET2026/</code>.</p><p>Der Schlüssel wird für das Windows-Konto mit DPAPI verschlüsselt. Nur ausdrücklich übersetzte Texte werden an OpenAI gesendet; die API-Anfrage setzt <code>store: false</code>. Internet und separate API-Abrechnung sind erforderlich. Ein ChatGPT-Abonnement ersetzt die API-Abrechnung nicht.</p><h2 id="updatefunktion-und-prufstand" tabindex="-1">Updatefunktion und Prüfstand <a class="header-anchor" href="#updatefunktion-und-prufstand" aria-label="Permalink to &quot;Updatefunktion und Prüfstand&quot;">​</a></h2><p><strong>GitHub-Updates werden manuell gestartet und vor der Installation bestätigt.</strong> Der alte Updateserver wird nicht verwendet. Google, LEO, Linguee und DeepL werden nicht mehr angeboten.</p><p>41 lokale Prüfungen mit simulierten API-Antworten sowie Debug- und Release-Builds prüfen Fehlerfälle, Abbruch, Wiederherstellung, Tabellenexport und die gerenderten Oberflächen in DE/EN/FR. Die Tests senden keine Texte an OpenAI. Ein echter API-Aufruf und die Qualität erzeugter Modellübersetzungen sind mit dem eigenen Zugang noch zu prüfen. Nicht jedes denkbare INI-Schema wird unterstützt; die inhaltliche Prüfung bleibt notwendig.</p><p>Das vollständige lokale Release 2.1.37 wurde vor der Veröffentlichung vom Nutzer kontrolliert und als funktionsfähig bestätigt. Das ZIP enthält beide Programme, die native Firebird-Laufzeit, die Originaldatenbank und das korrigierte Wörterbuch. ZIP-Integrität und SHA-256 wurden geprüft, alle sieben Datenbanktabellen wurden auf getrennten Kopien mit der Anzeige in DE/EN/FR verglichen. Die Bilder zeigen das aktuelle Design mit neutralen Daten und ohne private Einstellungen.</p>',39)])])}const m=n(l,[["render",o]]);export{f as __pageData,m as default};
